// Queue điểm touch cho Unity C# poll — xem PushTouchPoint()/Lidar_PollTouch() ở cuối file.
struct TouchPointXY { int x; int y; };
static std::mutex g_touch_queue_mutex;
static std::deque<TouchPointXY> g_touch_queue;
static constexpr size_t TOUCH_QUEUE_MAX = 32; // tránh phình nếu Unity ngừng poll (vd pause)

void PushTouchPoint(int x, int y) {
    std::lock_guard<std::mutex> lock(g_touch_queue_mutex);
    if (g_touch_queue.size() >= TOUCH_QUEUE_MAX) g_touch_queue.pop_front();
    g_touch_queue.push_back({x, y});
}

