void ld14p_parse_fnc(RingBuffer<uint8_t>& ld14p_data_queue, RingBuffer<DataPoint>& ld14p_point_queue) {

    /************** Debug only ********** */
#ifdef DEBUGING_TEST_PARSE
    size_t s_size = 0;
    do{
        std::this_thread::sleep_for(std::chrono::milliseconds(200));
    }while(debuging_uart_read_done == false);
    // LOGI(TAG, "LiDAR data almost ready >> parse it\n");

    s_size = ld14p_data_queue.getSize();
    std::cout << "============== data size = ";
    std::cout << std::dec << s_size << std::endl;
#endif
    /********************************** */
    // std::cout << "Enter ld14p_parse_fnc" << std::endl;
    LOGI(TAG, "Enter ld14p_parse_fnc");
    while (true) {
        uint8_t data;
         if (ld14p_data_queue.dequeue(data)) {
            if(lidar_AnalysisOne(data)){
                static int parse_log_counter = 0;
                if (++parse_log_counter % 100 == 1)
                    LOGI(TAG, "ld14p_parse_fnc packet OK #%d", parse_log_counter);

                DataPoint dpoints[12];
                size_t size = lidar_frame_Parse(dpoints);
                if(size > 0){
                    for(int i = 0; i < (int)size; i++){
                        if(ld14p_xypoint_is_valid(&dpoints[i]) == true){
                            ld14p_point_queue.enqueue(dpoints[i]);
                            is_xypoint_data_ready = true;
                        }
                    }
                }
            }

        } else {
            std::this_thread::sleep_for(std::chrono::microseconds(200));
        }
    }
    // std::cout << "Exit thread ld14p_parse_fnc" << std::endl;
    LOGI(TAG, "exit ld14p_parse_fnc");
}

void ld14p_parse_xypoint2touch_fnc(RingBuffer<DataPoint>& ld14p_point_queue) {

    // std::cout << "enter ld14p_parse_xypoint2touch_fnc" << std::endl;
    LOGI(TAG, "Enter ld14p_parse_xypoint2touch_fnc");

    touch_point_event_t pevent;
    DataPoint dpoint;

    // LOGI(TAG, "after while ld14p_parse_xypoint2touch_fnc");
    while (true) {
        if (ld14p_point_queue.dequeue(dpoint)) {

            // std::cout << "check point:(x/y) = " << std::setw(2) << std::setfill('0') << std::fixed << dpoint.x << "/" << std::setw(2) << std::setfill('0') << std::fixed << dpoint.y << ", size = " << std::setw(2) << std::setfill('0') << std::dec << ld14p_point_queue.getSize() << std::endl;
            if(point_is_in_area(&dpoint) == true){
                LidarPoint_t lp = {dpoint.x, dpoint.y, GetTimestamp()};
                // std::cout << "be lokked" << std::endl;
                std::lock_guard<std::mutex> lock(g_buffer_mutex);
                g_points_in_area_touch.push_back(lp);
                // g_points_in_area_swipe.push_back(lp);
                // std::cout << "DebugPoint: found a point is in the arear" << std::endl;
                // std::cout << "DebugPoint:found a point is in the arear (x/y) = " << std::setw(2) << std::setfill('0') << std::fixed << dpoint.x << "/" << dpoint.y << std::endl;
                // find_position(pevent);
                // LOGI(TAG, "exit ld14p_parse_xypoint2touch_fnc - g_points_in_area_touch.size() = %d", g_points_in_area_touch.size());
            }
            // std::cout << "Point is not in the area " << dpoint.x << "/" << dpoint.y << std ::endl;

            /************* */
            // std::cout << std::setw(2) << std::setfill('0') << std::fixed << dpoint.x << " / ";
            // std::cout << std::setw(2) << std::setfill('0') << std::fixed << dpoint.y << " ** ";
            // std::cout << std::setw(2) << std::setfill('0') << std::hex << (0x000000FssF & (int)dpoint.intensity) << "=====\n";
            /************* */
        } else {
            std::this_thread::sleep_for(std::chrono::microseconds(200));
        }
    }
    LOGI(TAG, "exit ld14p_parse_xypoint2touch_fnc");
}

// Các ngưỡng (cần điều chỉnh)
// const double MIN_SWIPE_DISTANCE = 0.15; // 15 cm
// const double MAX_SWIPE_DURATION = 0.50; // 500 ms

// Khai báo giả định cho các hàm/hằng số cần thiết
struct Coord2D { double x; double y; };
Coord2D convertLiDARToScreen(const LidarPoint_t& realPoint, int screenW, int screenH); 
const int P100_WIDTH = 1024; // Ví dụ
const int P100_HEIGH = 600; // Ví dụ
const double MIN_SWIPE_DISTANCE = 50; // Ví dụ (mét)
const double MAX_SWIPE_DURATION = 1000000000;  // Ví dụ (giây)


Coord2D convertLiDARToScreen(const LidarPoint_t& realPoint, int screenW, int screenH){
    int p100_x = 0, p100_y = 0;
    double x_avg = realPoint.x;
    double y_avg = realPoint.y;

    // p100_x = (P100_WIDTH - (((x_avg - (G_XMIN + G_SHIFT_X_FLOOR))/G_WIDTH_FLOOR) * P100_WIDTH)) + G_SHIFT_X;
    p100_x = (((x_avg - (G_XMIN + G_SHIFT_X_FLOOR))/G_WIDTH_FLOOR) * P100_WIDTH) + G_SHIFT_X;
    p100_y = (P100_HEIGH - (((y_avg - G_YMIN)/G_HIGHT_FLOOR) * P100_HEIGH)) + G_SHIFT_Y;
//    std::cout << "DebugTouchPoint: Touch point on phone(x/y) = " << std::setw(2) << std::setfill('0') << std::dec << p100_x << "/" << p100_y << std::endl;
    // std::cout << "Touch point on phone(x/y) = " << p100_x << "/" << p100_y << std::endl;
    // LOGI(TAG, "Touch point on phone(x/y) =  %d,, Y = %d", p100_x, p100_y);
//    sendTouch(300, 300);
    Coord2D result;
    result.x = (double)p100_x;
    result.y = (double)p100_y;
    return result;
}
static uint64_t g_last_swipe_timestamp = 0;
const uint64_t SWIPE_COOLDOWN_NS = 1000000000ULL;


void analyze_and_dispatch_swipe() {
    // LOGI(TAG, "enter analyze_and_dispatch_swipe");
    std::deque<touch_point_event_t> current_trajectory;
    {
        // Sử dụng std::deque<ToeEvent>& g_toe_history; và std::mutex g_history_mutex;
        std::lock_guard<std::mutex> lock(g_history_mutex);
        current_trajectory = g_toe_history; // Sao chép toàn bộ lịch sử hiện tại
    }
    // LOGI(TAG, "enter analyze_and_dispatch_swipe - size = %d", current_trajectory.size());
    if (current_trajectory.size() < 4) {
        return;
    }

    const auto& start_event = current_trajectory.front(); 
    const auto& end_event = current_trajectory.back();    
    
    // Tính toán Khoảng cách và Thời gian
    double total_distance = std::sqrt(
        std::pow(end_event.x_max_y - start_event.x_max_y, 2) + 
        std::pow(end_event.y_max_y - start_event.y_max_y, 2)
    );
    
    // Lưu ý: duration được tính bằng đơn vị thời gian của GetTimestamp()
    // Nếu GetTimestamp() trả về mili giây (ms), thì cần chia cho 1000.0
    uint64_t duration = end_event.timestamp - start_event.timestamp;
    
    // Giả định: duration đã tính bằng giây (hoặc đã được chuẩn hóa)
    
    // 3. Quyết định Vuốt (Swipe Decision)
    LOGI(TAG, "enter analyze_and_dispatch_swipe - total_distance = %f, duration= %lu", total_distance, duration);
    if (total_distance >= MIN_SWIPE_DISTANCE && duration <= MAX_SWIPE_DURATION) {
        
        // --- BƯỚC SỬA ĐỔI QUAN TRỌNG: CHUYỂN ĐỔI TỌA ĐỘ ---
        uint64_t current_time = GetTimestamp();
        { // Khóa mutex để truy cập g_last_swipe_timestamp
            std::lock_guard<std::mutex> lock(g_history_mutex); 
            
            // Nếu thời gian hiện tại trừ đi thời gian vuốt cuối cùng 
            // KHÔNG đủ lớn hơn 1 giây (SWIPE_COOLDOWN_NS), thì bỏ qua.
            if (current_time - g_last_swipe_timestamp < SWIPE_COOLDOWN_NS) {
                 LOGI(TAG, "SWIPE IGNORED: Cooldown active. Delta: %lu ns", current_time - g_last_swipe_timestamp);
                 // VẪN NÊN XÓA DỮ LIỆU ĐÃ PHÂN TÍCH để tránh lặp lại
                 g_toe_history.clear(); 
                 return;
            }
            // Nếu qua kiểm tra Cooldown, cập nhật dấu thời gian
            g_last_swipe_timestamp = current_time; 
        }

        // 1. Tạo LidarPoint_t từ ToeEvent để sử dụng hàm chuyển đổi
        LidarPoint_t start_lidar = {start_event.x_max_y, start_event.y_max_y, 0};
        LidarPoint_t end_lidar = {end_event.x_max_y, end_event.y_max_y, 0};
        
        // 2. Chuyển đổi sang tọa độ màn hình (pixel)
        Coord2D screen_start = convertLiDARToScreen(start_lidar, 1024, 600);
        Coord2D screen_end = convertLiDARToScreen(end_lidar, 1024, 600);
        
        // 3. GỌI HÀM GỬI LỆNH VUỐT
        sendSwipe((int)std::round(screen_start.x), (int)std::round(screen_start.y), 
                  (int)std::round(screen_end.x), (int)std::round(screen_end.y));

        LOGI(TAG, "Gui su kien vuot: (%.0f, %.0f) -> (%.0f, %.0f) in %.2lu s", 
             screen_start.x, screen_start.y, screen_end.x, screen_end.y, duration);
        
        // QUAN TRỌNG: Xóa quỹ đạo đã xử lý
        {
            std::lock_guard<std::mutex> lock(g_history_mutex);
            g_toe_history.clear(); 
        }

    } else if (total_distance < (MIN_SWIPE_DISTANCE / 2.0) && duration >= 0.5) {
        // HÀNH ĐỘNG CHẠM/GIỮ
        // ... (Giữ nguyên logic Tap/Hold nếu có)
    }
}

void ld14p_consumer_thread_function() {
    auto last_analysis_time = std::chrono::steady_clock::now();
    LOGI(TAG, "enter ld14p_consumer_thread_function");
    while (true) {
        auto now = std::chrono::steady_clock::now();
        // Kiểm tra xem đã đến lúc thực hiện phân tích cụm chưa (0.1s một lần)
        if (std::chrono::duration<double>(now - last_analysis_time).count() >= CLUSTER_ANALYSIS_INTERVAL) {
            
            // 1. SAO CHÉP DỮ LIỆU ĐỂ XỬ LÝ
            std::vector<LidarPoint_t> points_to_process;
            
            // BẢO VỆ VÀ TRUY CẬP VÙNG ĐỆM CHUNG
            {
                std::lock_guard<std::mutex> lock(g_buffer_mutex);
                points_to_process = g_points_in_area_touch;
            }
            // LOGI(TAG, "ld14p_consumer_thread_function Copied %zu points for processing.", points_to_process.size());
            // 2. LỌC THỜI GIAN VƯỢT NGƯỠNG (Cần được thực hiện trên VÙNG ĐỆM CHUNG)
            // Lọc và xóa các điểm cũ hơn MAX_POINT_LIFE_SEC
            uint64_t cutoff_time = GetTimestamp() - MAX_POINT_LIFE_SEC;
            
            // Cần khóa lại để xóa dữ liệu trong vùng đệm chung
            {
                std::lock_guard<std::mutex> lock(g_buffer_mutex);
               g_points_in_area_touch.erase(
                    std::remove_if(g_points_in_area_touch.begin(), g_points_in_area_touch.end(),
                        [cutoff_time](const LidarPoint_t& p) {
                            return p.timestamp < cutoff_time;
                        }),
                    g_points_in_area_touch.end()
                ); 
            }
            
            // 3. GOM CỤM VÀ TÌM TOE POINT (Sử dụng dữ liệu ĐÃ SAO CHÉP)
            if (points_to_process.size() > G_NUMS_POINT_REPORT) { // Đảm bảo có đủ dữ liệu
                // Gọi hàm gom cụm
                // LOGI(TAG, "Starting clustering on %zu points...", points_to_process.size());
                auto clusters = cluster_points(points_to_process);
                // LOGI(TAG, "Clustering completed. Found %zu potential clusters.", clusters.size());
                
                // Gọi hàm tìm điểm Y lớn nhất/Phân tích
                auto toe_events = find_toe_points(clusters, 3);
                
                // 4. THỰC HIỆN HÀNH ĐỘNG — chỉ dispatch cluster CÓ NHIỀU ĐIỂM NHẤT
                // (count cao nhất = vật thể thực/bàn chân, không phải nhiễu nền)
                if (!toe_events.empty()) {
                    for (const auto& event : toe_events) {
                        std::lock_guard<std::mutex> lock(g_history_mutex);
                        g_toe_history.push_back(event);
                    }
                    for (const auto& event : toe_events) {
                        report_touch_event(event);
                    }
                    double cutoff_time = GetTimestamp() - MAX_TRAJECTORY_LIFE;
                    while (!g_toe_history.empty() && g_toe_history.front().timestamp < cutoff_time) {
                        g_toe_history.pop_front();
                    }
                } else {
                    // LOGI(TAG, "Step 4: No valid Toe Point found (clusters too small or too few).");
                }
            }
            
            last_analysis_time = now;
        }
        
        // Ngủ ngắn để không kiểm tra mutex liên tục
        std::this_thread::sleep_for(std::chrono::milliseconds(1));
    }
    // std::cout << "exit ld14p_consumer_thread_function" << std::endl;
    LOGI(TAG, "exit ld14p_consumer_thread_function");
}

/***************/
struct ThreadArgs {
    RingBuffer<uint8_t>* byteQueue;
    RingBuffer<DataPoint>* pointQueue;
};

void* read_sensor_data_pthreadfnc(void* arg) {
    pthread_detach(pthread_self());

    auto* args = static_cast<ThreadArgs*>(arg);
    ld14p_read_fnc(*(args->byteQueue));

    delete args;
    return nullptr;
}

void* parse_sensor_data_pthreadfnc(void* arg) {
    pthread_detach(pthread_self());

    auto* args = static_cast<ThreadArgs*>(arg);
    ld14p_parse_fnc(*(args->byteQueue), *(args->pointQueue));

    delete args;
    return nullptr;
}

void* parse_touch_point_pthreadfnc(void* arg) {
    pthread_detach(pthread_self());

    auto* pointQueue = static_cast<RingBuffer<DataPoint>*>(arg);
    ld14p_parse_xypoint2touch_fnc(*pointQueue);

    delete pointQueue;
    return nullptr;
}


void* parse_cluster_find_point_in_group_pthreadfnc(void* arg) {
    pthread_detach(pthread_self());

    ld14p_consumer_thread_function();
    return nullptr;
}

void *lidar_processing_thread(void *arg) {
    // 1. Khởi tạo LidarProcessor (Được truyền hoặc tạo trong luồng)
    LidarProcessor processor; 
    
    // 2. Khai báo Buffer UART (Nơi lưu trữ dữ liệu thô)
    std::vector<unsigned char> uart_buffer;
    pthread_detach(pthread_self());
    // Vòng lặp xử lý liên tục
    if(uart_port_fd >= 0){
        while (true) {
            is_processing_thread_running = true;
            // --- A. ĐỌC DỮ LIỆU THÔ TỪ UART ---
            // Đọc dữ liệu thô từ cổng serial (Non-blocking read)
            std::vector<unsigned char> new_uart_data = read_uart_data();
            
            // --- B. XỬ LÝ KHUNG HÌNH ---
            // Truyền buffer thô hiện tại và dữ liệu mới đọc được vào hàm xử lý
            processor.process_frame(uart_buffer, new_uart_data);
            
            // Điều chỉnh độ trễ:
            // Cần độ trễ ngắn để tránh chiếm dụng CPU quá mức khi không có dữ liệu
            // usleep(1000) = 1ms
            usleep(1000); 
        }
    }
    else {
        LOGE(TAG, "Can't open uart port");
    }
    is_processing_thread_running = false;
    LOGI(TAG, "Exit reading LiDAR sensor");

    return nullptr;
}

// ---------------------------------------------------------------------------
// Unity-facing C API — plain functions, gọi qua [DllImport("liblidar_unity")] từ C#.
// Không JNIEnv/jobject nào ở đây: Java chỉ còn việc mở USB (UsbManager, xem
// LidarUsbBridge.java) rồi gọi Lidar_SetUartFd(fd) + Lidar_Init() một lần lúc khởi động.
// ---------------------------------------------------------------------------

extern "C" {

// Gọi 1 lần, SAU Lidar_SetUartFd(). Khởi động 4 thread đọc/parse/gom cụm/report — pipeline
// giống hệt bản gốc, chỉ khác điểm cuối (sendTouch → PushTouchPoint thay vì evdev/JNI).
void Lidar_Init() {
    if (is_processing_thread_running.load()) {
        LOGI(TAG, "Lidar_Init: threads already running, ignored");
        return;
    }
    if (uart_port_fd < 0) {
        LOGE(TAG, "Lidar_Init: uart_port_fd chưa set — gọi Lidar_SetUartFd() trước");
        return;
    }

    auto* ld14p_bytes_queue = new RingBuffer<uint8_t>(RINGBUFFER_SIZE);
    auto* ld14p_xypoint_queue = new RingBuffer<DataPoint>(RINGBUFFER_SIZE);
    pthread_t read_sensor_data_pthID, parse_sensor_data_pthID, parse_touch_point_pthID, parse_cluster_find_point_in_group_pthID;

    auto* readArgs = new ThreadArgs{ld14p_bytes_queue, nullptr};
    pthread_create(&read_sensor_data_pthID, nullptr, read_sensor_data_pthreadfnc, readArgs);

    auto* parseArgs = new ThreadArgs{ld14p_bytes_queue, ld14p_xypoint_queue};
    pthread_create(&parse_sensor_data_pthID, nullptr, parse_sensor_data_pthreadfnc, parseArgs);

    pthread_create(&parse_touch_point_pthID, nullptr, parse_touch_point_pthreadfnc, ld14p_xypoint_queue);

    pthread_create(&parse_cluster_find_point_in_group_pthID, nullptr, parse_cluster_find_point_in_group_pthreadfnc, nullptr);

    LOGI(TAG, "Lidar_Init: 4 threads started, uart_port_fd=%d", uart_port_fd);
}

// fd của pipe đọc dữ liệu USB (Java tạo qua ParcelFileDescriptor.createPipe(), bulk-transfer
// CP2102 → writeFd; native đọc từ readFd y hệt 1 UART thật). Gọi TRƯỚC Lidar_Init().
void Lidar_SetUartFd(int fd) {
    uart_port_fd = fd;
    LOGI(TAG, "Lidar_SetUartFd: uart_port_fd=%d", uart_port_fd);
}

// Tham số hiệu chỉnh vùng sàn — đọc từ file config (xem LidarConfig.cs phía Unity).
void Lidar_SendConfig(int half_x, int hight_floor, int ymax,
                       int shift_x_floor, int shift_y, int shift_x,
                       int offset_angle, int nums_point_report) {
    G_HALF_X = half_x;
    G_HIGHT_FLOOR = hight_floor;
    G_YMAX = ymax;
    G_SHIFT_X_FLOOR = shift_x_floor;
    G_SHIFT_Y = shift_y;
    G_SHIFT_X = shift_x;
    G_OFFSET_ANGLE = static_cast<float>(offset_angle);
    G_NUMS_POINT_REPORT = nums_point_report;

    G_YMIN = G_YMAX - G_HIGHT_FLOOR;
    G_WIDTH_FLOOR = 2 * G_HALF_X;
    G_XMAX = G_HALF_X + G_SHIFT_X_FLOOR;
    G_XMIN = -G_HALF_X + G_SHIFT_X_FLOOR;
    LOGI(TAG, "Lidar_SendConfig: half_x=%d hight_floor=%d ymax=%d shift_x_floor=%d shift_y=%d shift_x=%d offset_angle=%f nums_point_report=%d",
         G_HALF_X, G_HIGHT_FLOOR, G_YMAX, G_SHIFT_X_FLOOR, G_SHIFT_Y, G_SHIFT_X, G_OFFSET_ANGLE, G_NUMS_POINT_REPORT);
}

void Lidar_SetTouchEnabled(int enabled) {
    g_touch_enabled.store(enabled != 0);
    LOGI(TAG, "Lidar_SetTouchEnabled → %s", enabled ? "ON" : "OFF");
}

// Gọi mỗi frame từ Unity Update(). Trả 1 nếu có điểm mới (ghi vào *outX/*outY, không gian
// tham chiếu 1024x600 — xem convert_to_1024x600() trong liblidar.cpp), 0 nếu queue rỗng.
int Lidar_PollTouch(int* outX, int* outY) {
    std::lock_guard<std::mutex> lock(g_touch_queue_mutex);
    if (g_touch_queue.empty()) return 0;
    TouchPointXY p = g_touch_queue.front();
    g_touch_queue.pop_front();
    if (outX) *outX = p.x;
    if (outY) *outY = p.y;
    return 1;
}

} // extern "C"